import{_ as e,c as o,o as t,a4 as c}from"./chunks/framework.BYxathSa.js";const f=JSON.parse('{"title":"Q23：前端性能优化的整体方案","description":"","frontmatter":{},"headers":[],"relativePath":"frontend/q23.md","filePath":"frontend/q23.md","lastUpdated":null}'),l={name:"frontend/q23.md"},d=c('<h1 id="q23-前端性能优化的整体方案" tabindex="-1">Q23：前端性能优化的整体方案 <a class="header-anchor" href="#q23-前端性能优化的整体方案" aria-label="Permalink to &quot;Q23：前端性能优化的整体方案&quot;">​</a></h1><p><strong>网络/加载优化</strong></p><ul><li>代码压缩：JS/CSS/HTML 压缩，开启 Gzip/Brotli。</li><li>图片优化：使用 WebP/AVIF，响应式图片 <code>srcset</code>，懒加载（<code>loading=&quot;lazy&quot;</code> 或 IntersectionObserver），雪碧图。</li><li>缓存策略：设置强缓存+协商缓存，文件名 Hash 变化更新。</li><li>CDN 加速资源分发。</li><li>按需加载：路由懒加载、组件动态 import。</li><li>预加载/预连接：<code>&lt;link rel=&quot;preload&quot;&gt;</code> 提前载入关键资源，<code>preconnect</code> 缩短握手时间，<code>prefetch</code> 预先获取将来资源。</li><li>服务端渲染（SSR）或预渲染，首屏加速。</li></ul><p><strong>渲染/交互优化</strong></p><ul><li>避免强制同步布局（布局抖动），如循环中读 <code>offsetHeight</code> 后又改样式。</li><li>使用 <code>will-change</code> 或 <code>transform: translate3d(0,0,0)</code> 创建独立合成层，避免重排重绘。</li><li>动画使用 <code>requestAnimationFrame</code>，而不是定时器。</li><li>长列表启用虚拟滚动。</li><li>事件处理使用防抖（输入搜索）和节流（滚动事件）。</li></ul><p><strong>框架层面</strong></p><ul><li>Vue/React：合理拆分组件，<code>React.memo</code>/<code>PureComponent</code>、<code>shouldComponentUpdate</code> 避免不必要渲染，Vue中用 <code>computed</code> 和 <code>v-once</code>。</li><li>列表正确使用 <code>key</code>，防止就地复用导致状态错误。</li></ul>',7),i=[d];function n(a,r,s,p,_,u){return t(),o("div",null,i)}const h=e(l,[["render",n]]);export{f as __pageData,h as default};
